UPDATE sync_checkpoints
SET state_json = JSON_SET(state_json, '$.fingerprint', #{nextFingerprint}), updated_at = UTC_TIMESTAMP()
WHERE task_id = #{taskId}
  AND JSON_UNQUOTE(JSON_EXTRACT(state_json, '$.fingerprint')) = #{previousFingerprint}
  AND JSON_UNQUOTE(JSON_EXTRACT(state_json, '$.token')) = #{previousToken}
  AND JSON_UNQUOTE(JSON_EXTRACT(state_json, '$.readerMode')) = 'mysql-date-tables-v1'
  AND JSON_UNQUOTE(JSON_EXTRACT(state_json, '$.complete')) = 'true'
